test('lineTotal and lineDiscount work together in lineVat', () => {
  const line = { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 5 };
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const base = total - discount;
  const expectedVat = Math.round(base * 21 / 100);
  assert.equal(lineVat(line), expectedVat);
});

test('bulk discount does not apply for qty < 10', () => {
  const line = { sku: 'ITEM', qty: 9, unitPrice: 1000, name: 'Item', vatRate: 21, discountPercent: 0 };
  const total = lineTotal(line);
  const vat = lineVat(line);
  const expectedVat = Math.round(total * 21 / 100);
  assert.equal(vat, expectedVat);
});

test('bulk discount applies for qty = 10', () => {
  const line = { sku: 'ITEM', qty: 10, unitPrice: 1000, name: 'Item', vatRate: 21, discountPercent: 0 };
  const total = lineTotal(line);
  const bulkDiscountAmount = total * 2.5 / 100;
  const remaining = total - bulkDiscountAmount;
  const expectedVat = Math.round(remaining * 21 / 100);
  assert.equal(lineVat(line), expectedVat);
});

test('bulk discount applies for qty > 10', () => {
  const line = { sku: 'ITEM', qty: 15, unitPrice: 1000, name: 'Item', vatRate: 21, discountPercent: 0 };
  const total = lineTotal(line);
  const bulkDiscountAmount = total * 2.5 / 100;
  const remaining = total - bulkDiscountAmount;
  const expectedVat = Math.round(remaining * 21 / 100);
  assert.equal(lineVat(line), expectedVat);
});

test('bulk discount is 2.5% of remaining after first discount', () => {
  const line = { sku: 'ITEM', qty: 10, unitPrice: 10000, name: 'Item', vatRate: 21, discountPercent: 10 };
  const total = lineTotal(line);
  const firstDiscount = total * 10 / 100;
  const remaining = total - firstDiscount;
  const bulkDiscountAmount = remaining * 2.5 / 100;
  const finalAmount = remaining - bulkDiscountAmount;
  const expectedVat = Math.round(finalAmount * 21 / 100);
  assert.equal(lineVat(line), expectedVat);
});

test('invoiceTotals includes bulk discount in discount field', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-01',
    status: 'issued',
    lines: [
      { sku: 'ITEM', qty: 10, unitPrice: 1000, name: 'Item', vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const total = 10000;
  const bulkDiscount = total * 2.5 / 100;
  assert.equal(totals.discount, bulkDiscount);
});

test('invoiceTotals with line discount and bulk discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-01',
    status: 'issued',
    lines: [
      { sku: 'ITEM', qty: 10, unitPrice: 10000, name: 'Item', vatRate: 21, discountPercent: 10 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const subtotal = 100000;
  const lineDiscount = 10000;
  const remaining = 90000;
  const bulkDiscount = remaining * 2.5 / 100;
  const totalDiscount = lineDiscount + bulkDiscount;
  assert.equal(totals.discount, totalDiscount);
});

test('invoiceTotals VAT calculated after bulk discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-01',
    status: 'issued',
    lines: [
      { sku: 'ITEM', qty: 10, unitPrice: 10000, name: 'Item', vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const subtotal = 100000;
  const bulkDiscount = subtotal * 2.5 / 100;
  const baseForVat = subtotal - bulkDiscount;
  const expectedVat = Math.round(baseForVat * 21 / 100);
  assert.equal(totals.vat, expectedVat);
});

test('invoiceTotals with multiple lines, only qty >= 10 gets bulk discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-01',
    status: 'issued',
    lines: [
      { sku: 'ITEM1', qty: 5, unitPrice: 1000, name: 'Item1', vatRate: 21, discountPercent: 0 },
