  };
  const totals = invoiceTotals(invoice);
  const subtotal = 5000 + 10000 + 15000;
  const bulkDiscount1 = 0;
  const bulkDiscount2 = 10000 * 2.5 / 100;
  const bulkDiscount3 = 15000 * 2.5 / 100;
  const totalDiscount = bulkDiscount1 + bulkDiscount2 + bulkDiscount3;
  assert.equal(totals.discount, totalDiscount);
});

test('bulk discount with large quantity', () => {
  const line = { sku: 'ITEM', qty: 1000, unitPrice: 100000, name: 'Item', vatRate: 21, discountPercent: 0 };
  const total = lineTotal(line);
  const bulkDiscountAmount = total * 2.5 / 100;
  const remaining = total - bulkDiscountAmount;
  const expectedVat = Math.round(remaining * 21 / 100);
  assert.equal(lineVat(line), expectedVat);
});

test('bulk discount edge case qty = 9', () => {
  const line = { sku: 'ITEM', qty: 9, unitPrice: 10000, name: 'Item', vatRate: 21, discountPercent: 0 };
  const total = lineTotal(line);
  const expectedVat = Math.round(total * 21 / 100);
  assert.equal(lineVat(line), expectedVat);
});

