  const remaining = total - lineDiscount;
  const bulk = remaining * 2.5 / 100;
  const baseForVat = remaining - bulk;
  const expectedVat = Math.round(baseForVat * 9 / 100);
  assert.equal(lineVat(line), expectedVat);
});

test('invoiceTotals total with bulk discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-01',
    status: 'issued',
    lines: [
      { sku: 'ITEM', qty: 10, unitPrice: 10000, name: 'Item', vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const subtotal = 100000;
  const bulkDiscount = subtotal * 2.5 / 100;
  const baseForVat = subtotal - bulkDiscount;
  const vat = Math.round(baseForVat * 21 / 100);
